+        .filter_map(|e| e.ok())
+        .filter_map(|e| e.file_name().to_str().map(str::to_owned))
+        .collect();
+    got.sort();
+    let mut want: Vec<String> = recorded::CASES.iter().map(|c| format!("{c}.cnc")).collect();
+    want.sort();
+    assert_eq!(got, want);
+}
